import re

def parse_num(val):
    if val is None or val == '—' or val == '__' or val == '':
        return None
    val = val.strip().replace(',', '').replace('$', '').replace('€', '').replace(' ', '')
    if val.startswith('(') and val.endswith(')'):
        val = '-' + val[1:-1]
    try:
        return float(val)
    except ValueError:
        return None

def get_scale(node):
    # Search for scale indicators in the table cells or title
    text = (node.get('text', '') or '').lower()
    if node['kind'] == 'table':
        for row in node['table']['rows']:
            for cell in row:
                text += ' ' + (cell or '').lower()

    if 'thousands' in text or '000' in text:
        return 1000.0
    if 'millions' in text or ' million' in text or 'm' in text.split():
        # Note: 'm' can be tricky, but in financial reports often denotes millions
        return 1000000.0
    return 1.0

def extract_years(columns):
    years = []
    for col in columns:
        if not col: continue
        match = re.search(r'(\d{4})', col)
        if match:
            years.append(int(match.group(1)))
    return sorted(years)

