    if not node: return []

    scope_nodes = scope_nodes(doc, node)
    inputs_list = []

    for sn in scope_nodes:
        if sn['kind'] != 'table': continue
        cols = sn['table']['columns']
        rows = sn['table']['rows']
        years = extract_years(cols)

        # Identify "Beginning Balance" type columns
        beg_col_idx = None
        for idx, col in enumerate(cols):
            if col and ('beginning' in col.lower() or 'start' in col.lower()):
                beg_col_idx = idx
                break

        for i, row in enumerate(rows):
            label = row[0] if row else None
            if not label or not label.strip(): continue
            entity_id = label.strip()

            # Case 1: Beginning balance column
            if beg_col_idx is not None and beg_col_idx < len(row):
                val = parse_num(row[beg_col_idx])
                if val is not None:
                    inputs_list.append({
                        "id": f"input_{sn['node_id']}_{i}",
                        "time": None,
                        "kind": "state",
                        "entities": [entity_id],
                        "fields": {"value": val},
                        "src": [sn['node_id'], i, [cols[beg_col_idx]]]
                    })

            # Case 2: Oldest year in a multi-year table
            elif years:
                min_year = years[0]
                min_year_idx = -1
                for idx, col in enumerate(cols):
                    if str(min_year) in (col or ''):
                        min_year_idx = idx
                        break

                if min_year_idx != -1 and min_year_idx < len(row):
                    val = parse_num(row[min_year_idx])
                    if val is not None:
                        inputs_list.append({
                            "id": f"input_{sn['node_id']}_{i}_{min_year}",
                            "time": float(min_year),
                            "kind": "state",
                            "entities": [entity_id],
                            "fields": {"value": val},
                            "src": [sn['node_id'], i, [cols[min_year_idx]]]
                        })

    return inputs_list

