import re

def parse_num(val):
    if val is None:
        return None
    val = str(val).strip()
    if val in ('—', '__', '', 'None', 'nan'):
        return None

    # Handle percentages
    if val.endswith('%'):
        val = val.replace('%', '')
        try:
            return float(val) / 100.0
        except ValueError:
            return None

    # Remove currency symbols and commas
    val = val.replace(',', '').replace('$', '').replace('€', '').replace('£', '').strip()

    # Handle parentheses for negative numbers
    if val.startswith('(') and val.endswith(')'):
        val = '-' + val[1:-1]

    try:
        return float(val)
    except ValueError:
        return None

def extract_year(text):
    if not text:
        return None
    match = re.search(r'\b(19|20)\d{2}\b', text)
    if match:
        return int(match.group(0))
    return None

